include { BEDTOOLS_SPLIT } from 'nf-core/bedtools/split'

workflow BED_SCATTER_BEDTOOLS {
    take:
    ch_bed // channel: [ val(meta), path(bed), val(scatter_count) ]

    main:
    BEDTOOLS_SPLIT(ch_bed)

    // Checks if the scatter count corresponds to the amount of files created. (This doesn't match in some edge cases)
    ch_scattered_beds = BEDTOOLS_SPLIT.out.beds
        .map { meta, beds ->
            def scatter_count = beds instanceof Path ? 1 : beds.size()
            [meta, beds, scatter_count]
        }
        .transpose()

    emit:
    scattered_beds = ch_scattered_beds // channel: [ val(meta), path(bed), val(scatter_count) ]
}

nextflow_workflow {

    name "Test Workflow BED_SCATTER_BEDTOOLS"

    script "../main.nf"
    workflow "BED_SCATTER_BEDTOOLS"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/bed_scatter_bedtools"
    tag "bed_scatter_bedtools"
    tag "bedtools/split"
    tag "bedtools"

    test("homo_sapiens - bed - 3") {
        when {
            workflow {
                """
                input[0] = Channel.of([
                    [id:'test'],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.multi_intervals.bed', checkIfExists:true),
                    3
                ])
                """
            }
        }
        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(workflow.out).match() }
            )
        }
    }

    test("homo_sapiens - bed - 4 -- stub") {
        options "-stub"
        when {
            workflow {
                """
                input[0] = Channel.of([
                    [id:'test'],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.multi_intervals.bed', checkIfExists:true),
                    4
                ])
                """
            }
        }
        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(workflow.out).match() }
            )
        }
    }
}
